import { dailyIndex } from "@/lib/daily";
import type { Localized } from "@/lib/i18n";
import data from "./data/people.json";

// data/people.json is generated by scripts/fetch-people.mjs — don't edit it
// by hand; add people or corrections in scripts/people-roster.mjs instead.

export type Place = {
  name: Localized;
  country: Localized | null;
  lat: number;
  lon: number;
};

export type LifeEvent = { year: number; place: Place };

export type Person = {
  id: string;
  qid: string;
  name: Localized;
  description: Localized;
  extract: { en: string; pt: string | null };
  wiki: { en: string; pt: string | null };
  image: { src: string; width: number; height: number } | null;
  birth: LifeEvent;
  death: LifeEvent;
};

export const PEOPLE = data as Person[];

const byId = new Map(PEOPLE.map((person) => [person.id, person]));

export const personById = (id: string): Person | undefined => byId.get(id);

export function personForDay(day: number): Person {
  return PEOPLE[dailyIndex(PEOPLE.length, day, "who-when-where")];
}

/** "Shrewsbury, United Kingdom" */
export function placeLabel(place: Place, locale: keyof Localized): string {
  const name = place.name[locale];
  const country = place.country?.[locale];
  return country && country !== name ? `${name}, ${country}` : name;
}
